package main

import (
	"fmt"
	"math"
)

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	var n int
	fmt.Scan(&n)

	ara := make([][4]int, n)
	for i := 0; i < n; i++ {
		for j := 0; j < 4; j++ {
			fmt.Scan(&ara[i][j])
		}
	}

	f := 0
	for i := 0; i < n; i++ {
		s := abs(ara[i][0] - ara[i][2])
		t := abs(ara[i][1] - ara[i][3])
		f += s * t
	}

	mini := 100000
	min := 100000
	maxi := 0
	max := 0

	for i := 0; i < n; i++ {
		if ara[i][0] < mini {
			mini = ara[i][0]
		}
		if ara[i][1] < min {
			min = ara[i][1]
		}
		if ara[i][2] > maxi {
			maxi = ara[i][2]
		}
		if ara[i][3] > max {
			max = ara[i][3]
		}
	}

	w := (maxi - mini) * (max - min)

	if f == w && (maxi-mini) == (max-min) {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

